import sys
import subprocess
import html
from pathlib import Path

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    input_path = Path(sys.argv[1])
    if not input_path.exists() or not input_path.is_file():
        sys.exit(1)

    with open(input_path, 'r', encoding='utf-8') as f:
        lines = [line.strip() for line in f if line.strip()]

    html_content = []
    for line in lines:
        cmd, expr = line.split(' :: ', 1)
        try:
            result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
            stdout = result.stdout.strip()
            try:
                value = eval(expr, {'stdout': stdout})
            except Exception as e:
                value = f"Error evaluating expression: {e}"
        except subprocess.CalledProcessError as e:
            value = f"Command failed: {e.stderr.strip()}"

        html_content.append(f'<pre>{html.escape(str(value))}</pre>')

    with open('report.html', 'w', encoding='utf-8') as f:
        f.write(''.join(html_content))

if __name__ == '__main__':
    main()

import sys
import subprocess
import html
from io import StringIO

def process_line(line):
    parts = line.split(' :: ', 1)
    if len(parts) < 2:
        return None
    cmd, expr = parts
    try:
        result = subprocess.run(cmd, shell=True, check=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout_text = result.stdout
        try:
            eval_result = eval(expr, {'stdout': stdout_text})
            return str(eval_result)
        except Exception:
            return None
    except subprocess.CalledProcessError as e:
        return None

def main():
    html_content = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        result = process_line(line)
        if result is not None:
            html_content.append(f'<pre>{html.escape(result)}</pre>')
    with open('report.html', 'w', encoding='utf-8') as f:
        f.write(''.join(html_content))

if __name__ == '__main__':
    main()
